using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["appName"] = "MyService",
        ["version"] = "1.0.0",
        ["maxRetries"] = 3,
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["betaFeatures"] = false
        }
    };

    [McpServerResource(UriTemplate = "config://app", Name = "app-config",
        Title = "Application Configuration", MimeType = "application/json")]
    [Description("Returns the current application configuration as JSON.")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/features/{featureName}", Name = "feature-flag",
        Title = "Feature Flag", MimeType = "application/json")]
    [Description("Returns the status of a specific feature flag.")]
    public static string GetFeatureFlag(string featureName)
    {
        var features = (Dictionary<string, bool>)AppConfig["features"];
        var result = new
        {
            feature = featureName,
            enabled = features.TryGetValue(featureName, out var enabled) && enabled,
            found = features.ContainsKey(featureName)
        };
        return JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true });
    }
}

